import { Fragment, FunctionalComponent } from 'preact';
import styles from './styles.module.scss';

const textStyles =
  typeof window === 'undefined' ? { color: 'transparent' } : {};

const formatNumber = (number: number) => {
  // If the number is more than 10000, then we want to abbreviate it
  if (number > 10000) {
    // If the number is more than 1000000, then we want to abbreviate it
    if (number > 1000000) {
      return `${(number / 1000000).toFixed(1)}M`;
    }

    return `${(number / 1000).toFixed(1)}K`;
  }

  return number;
};

const Counter: FunctionalComponent = () => {
  const state = localStorage.getItem('state');

  const parsedState = JSON.parse(state || '{}');

  const communityTotal = parsedState?.totalCounter?.lastSeen?.total || 0;
  const communityBottles = formatNumber(Math.floor(communityTotal / 5));

  return (
    <div
      style={{
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        flexDirection: 'row',
        gap: '2rem',
      }}
    >
      <div
        className={`${styles.counterOuter} ${styles.bottlesCounter} bottlesCounterTC`}
      >
        <Fragment>
          <div className={`${styles.counter}`}>
            <div className={`${styles.counterIcon} ${styles.bottle}`} />
            <span style={textStyles}>{communityBottles} bottles saved</span>
          </div>
        </Fragment>
      </div>
    </div>
  );
};

export default Counter;
