import { FunctionalComponent, render } from 'preact';
import './styles.module.scss';
import { ThemeProvider } from '@material-ui/core';
import styles from './styles.module.scss';
import theme from '../newtab/theme';
import Counter from './Counter';
import '@fontsource/poppins';
import '@fontsource/poppins/700.css';
const isExtension = () => {
  try {
    return chrome.runtime.id !== undefined;
  } catch (e) {
    return false;
  }
};

const isTabsPermissionGranted = () => {
  return new Promise((resolve) => {
    chrome.permissions.contains(
      {
        permissions: ['tabs'],
      },
      (result) => {
        resolve(result);
      }
    );
  });
};

const links = [
  {
    name: 'Bookmarks',
    url: 'chrome://bookmarks',
    icon: '/img/bookmarks.webp',
  },
  {
    name: 'History',
    url: 'chrome://history',
    icon: '/img/history.webp',
  },
  {
    name: 'Downloads',
    url: 'chrome://downloads',
    icon: '/img/downloads.webp',
  },
  {
    name: 'Settings',
    url: 'chrome://settings',
    icon: '/img/settings.webp',
  },
];

const App: FunctionalComponent = () => {
  const isExt = isExtension();

  const navigateTo = (url: string) => {
    if (isExt) {
      isTabsPermissionGranted().then((result) => {
        if (!result) {
          chrome.permissions.request(
            {
              permissions: ['tabs'],
            },
            (granted) => {
              if (granted) {
                chrome.tabs.create({ url });
              }
            }
          );
        } else {
          chrome.tabs.create({ url });
        }
      });
    } else {
      window.open(url);
    }
  };

  return (
    <ThemeProvider theme={theme}>
      <div
        class={styles.mainContainer}
        style={{
          height: process.env.TARGET_BROWSER === 'safari' ? '11.5rem' : '20rem',
        }}
      >
        <div class={styles.header}>
          <span class={styles.headerTitle}>Contributions so far</span>
          <Counter />
        </div>

        {process.env.TARGET_BROWSER !== 'safari' && (
          <div class={styles.body}>
            {links.map((link) => (
              <button key={link.name} onClick={() => navigateTo(link.url)}>
                <img src={link.icon} alt={link.name} draggable={false} />
                <span>{link.name}</span>
              </button>
            ))}
          </div>
        )}

        <div class={styles.footer}>
          <img draggable={false} src="/img/logo-white.webp" alt="OceanHero" />

          <div class={styles.footerLinks}>
            {/* <a href="https://oceanhero.today" target="_blank">
                Blog
              </a> */}

            <a
              href="https://oceanhero.today/about-us"
              target="_blank"
              rel="noreferrer"
            >
              About
            </a>
          </div>
        </div>

        <img src="/img/popup-bg.webp" class={styles.bg} />
      </div>
    </ThemeProvider>
  );
};

render(<App />, document.getElementById('root'));
